class Screen
  def initialize
    @lock = Mutex.new
    @buffers = [[], []]
    @current = 0
  end

  def back;    @buffers[1 - @current]; end
  def current; @buffers[@current];     end
  def swap;    @lock.synchronize { @current = 1 - @current }; end
end

